SELECT * FROM facts)
, bounds AS (SELECT min(order_datetime_local) first_at,max(order_datetime_local) last_at FROM f),
 periods(period) AS (VALUES ('day'),('week'),('month')),
 calendar AS (SELECT p.period,generate_series(date_trunc(p.period,first_at),date_trunc(p.period,last_at),('1 '||p.period)::interval)::date period_start FROM bounds CROSS JOIN periods p),
 grouped AS (SELECT p.period,date_trunc(p.period,f.order_datetime_local)::date period_start,count(*) orders,sum(gross_order_value_gbp) gross_value FROM f CROSS JOIN periods p GROUP BY 1,2),
 filled AS (SELECT c.period,c.period_start,COALESCE(g.orders,0) orders,COALESCE(g.gross_value,0) gross_value FROM calendar c LEFT JOIN grouped g USING(period,period_start))
 SELECT *,orders-lag(orders) over(partition by period order by period_start) change_in_orders,
 sum(gross_value) over(partition by period order by period_start rows unbounded preceding) cumulative_gross_value FROM filled ORDER BY period,period_start;

