SELECT CASE WHEN raw_preparation_minutes IS NULL THEN 'Missing pair'
 WHEN raw_preparation_minutes<0 THEN 'Invalid negative'
 WHEN preparation_minutes<=5 THEN '0–5 min' WHEN preparation_minutes<=15 THEN '5–15 min'
 WHEN preparation_minutes<=30 THEN '15–30 min' WHEN preparation_minutes<=60 THEN '30–60 min'
 WHEN preparation_minutes<=120 THEN '60–120 min' WHEN preparation_minutes<=1440 THEN '120–1440 min'
 ELSE 'Over 24 hours' END duration_band,count(*) orders FROM f GROUP BY 1 ORDER BY 1;

