SELECT count(preparation_minutes) timed_orders,avg(preparation_minutes) mean_prep,
 percentile_cont(.5) within group(order by preparation_minutes) median_prep,
 percentile_cont(.9) within group(order by preparation_minutes) p90_prep,max(preparation_minutes) max_prep,
 avg(preparation_minutes) FILTER(WHERE preparation_minutes<=120) sensitivity_mean_le120,
