SELECT count(*) orders,count(*)-count(distinct order_id) duplicate_ids,
 sum(missing_created) missing_created,sum(missing_preparing) missing_preparing,sum(missing_ready) missing_ready,
 sum(missing_completed) missing_completed,sum(missing_acknowledged) missing_acknowledged,
 sum(invalid_timestamp_sequence) invalid_sequences,sum(money_warning) money_warnings,
 sum(invalid_items_container) invalid_containers,sum(empty_items) empty_arrays,sum(invalid_item_lines) invalid_lines,
 count(*) FILTER(WHERE abs(item_subtotal_delta_gbp)>.01) item_subtotal_mismatches,
 count(*) FILTER(WHERE abs(order_total_delta_gbp)>.01) order_total_mismatches,
 sum(inconsistent_payment_state) inconsistent_payments,
 (SELECT count(*) FROM public.kitchen_notification_outbox n LEFT JOIN public.orders o ON o.id=n.order_id WHERE o.id IS NULL) orphan_notification_events
 FROM f;

